query GetShop {
  shop {
    id
    name
    email
    currencyCode
    ianaTimezone
    plan { publicDisplayName shopifyPlus }
    primaryDomain { url }
  }
}

query ListLocations($first: Int!, $after: String) {
  locations(first: $first, after: $after, includeInactive: false) {
    nodes {
      id
      name
      isActive
      fulfillsOnlineOrders
      address { address1 city province countryCode zip }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query ListProducts($first: Int!, $after: String, $query: String) {
  products(first: $first, after: $after, query: $query) {
    nodes {
      id
      title
      handle
      status
      vendor
      productType
      tags
      updatedAt
      featuredMedia { preview { image { url altText } } }
      variants(first: 100) {
        nodes { id title sku price barcodes(first: 5) { nodes { type value } } inventoryItem { id } }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query GetProduct($id: ID!) {
  product(id: $id) {
    id
    title
    descriptionHtml
    status
    vendor
    productType
    tags
    media(first: 50) {
      nodes {
        id
        mediaContentType
        ... on MediaImage { image { url altText width height } }
      }
    }
    variants(first: 100) {
      nodes { id title sku price compareAtPrice barcodes(first: 5) { nodes { type value } } inventoryItem { id tracked } }
    }
  }
}

query FindVariantsBySku($query: String!, $first: Int!) {
  productVariants(first: $first, query: $query) {
    nodes {
      id
      sku
      barcodes(first: 5) { nodes { type value } }
      displayName
      product { id title }
      inventoryItem { id }
    }
  }
}

mutation AddProductImage($productId: ID!, $media: [CreateMediaInput!]!) {
  productUpdate(product: { id: $productId }, media: $media) {
    product {
      id
      media(first: 10) { nodes { id status mediaContentType } }
    }
    userErrors { field message }
  }
}

query ListInventoryAtLocation($locationId: ID!, $first: Int!, $after: String) {
  location(id: $locationId) {
    id
    name
    inventoryLevels(first: $first, after: $after) {
      nodes {
        id
        item { id sku tracked variants(first: 1) { nodes { id displayName } } }
        quantities(names: ["available", "on_hand", "committed", "incoming"]) { name quantity }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}

query GetInventoryItem($id: ID!) {
  inventoryItem(id: $id) {
    id
    sku
    tracked
    unitCost { amount currencyCode }
    variants(first: 1) { nodes { id displayName } }
    inventoryLevels(first: 50) {
      nodes {
        location { id name }
        quantities(names: ["available", "on_hand"]) { name quantity }
      }
    }
  }
}

mutation AdjustInventory($input: InventoryAdjustQuantitiesInput!) {
  inventoryAdjustQuantities(input: $input) {
    inventoryAdjustmentGroup {
      createdAt
      reason
      changes { name delta quantityAfterChange item { id } location { id } }
    }
    userErrors { field message }
  }
}

mutation SetInventory($input: InventorySetQuantitiesInput!) {
  inventorySetQuantities(input: $input) {
    inventoryAdjustmentGroup {
      reason
      changes { name delta quantityAfterChange }
    }
    userErrors { field message }
  }
}

query ListInventoryTransfers($first: Int!, $after: String, $query: String) {
  inventoryTransfers(first: $first, after: $after, query: $query) {
    nodes {
      id
      name
      status
      referenceName
      dateCreated
      totalQuantity
      receivedQuantity
      origin { name location { id } }
      destination { name location { id } }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query GetInventoryTransfer($id: ID!) {
  inventoryTransfer(id: $id) {
    id
    name
    status
    note
    origin { name location { id } }
    destination { name location { id } }
    lineItems(first: 100) {
      nodes { id title totalQuantity shippedQuantity inventoryItem { id sku } }
    }
    shipments(first: 10) {
      nodes { id name status totalReceivedQuantity }
    }
  }
}

mutation CreateInventoryTransfer($input: InventoryTransferCreateInput!) {
  inventoryTransferCreate(input: $input) {
    inventoryTransfer { id name status totalQuantity }
    userErrors { field message }
  }
}

mutation MarkTransferReadyToShip($id: ID!) {
  inventoryTransferMarkAsReadyToShip(id: $id) {
    inventoryTransfer { id status }
    userErrors { field message }
  }
}

mutation ReceiveInventoryShipment($id: ID!, $lineItems: [InventoryShipmentReceiveItemInput!]) {
  inventoryShipmentReceive(id: $id, lineItems: $lineItems) {
    inventoryShipment { id status totalReceivedQuantity }
    userErrors { field message }
  }
}

query ListOrders($first: Int!, $after: String, $query: String) {
  orders(first: $first, after: $after, query: $query, sortKey: CREATED_AT, reverse: true) {
    nodes {
      id
      name
      createdAt
      displayFinancialStatus
      displayFulfillmentStatus
      totalPriceSet { shopMoney { amount currencyCode } }
      customer { id displayName }
      lineItems(first: 50) {
        nodes { id title sku quantity variant { id } }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query GetOrder($id: ID!) {
  order(id: $id) {
    id
    name
    createdAt
    cancelledAt
    displayFinancialStatus
    displayFulfillmentStatus
    currencyCode
    subtotalPriceSet { shopMoney { amount currencyCode } }
    totalTaxSet { shopMoney { amount currencyCode } }
    totalPriceSet { shopMoney { amount currencyCode } }
    customer { id displayName defaultEmailAddress { emailAddress } }
    shippingAddress { address1 city province countryCodeV2 zip }
    lineItems(first: 100) {
      nodes {
        id
        title
        sku
        quantity
        originalUnitPriceSet { shopMoney { amount currencyCode } }
        variant { id inventoryItem { id } }
      }
    }
    fulfillments { id status createdAt location { id name } }
  }
}

query ListCustomers($first: Int!, $after: String, $query: String) {
  customers(first: $first, after: $after, query: $query) {
    nodes {
      id
      displayName
      defaultEmailAddress { emailAddress }
      defaultPhoneNumber { phoneNumber }
      numberOfOrders
      amountSpent { amount currencyCode }
      tags
      updatedAt
    }
    pageInfo { hasNextPage endCursor }
  }
}

query GetCustomer($id: ID!) {
  customer(id: $id) {
    id
    firstName
    lastName
    displayName
    defaultEmailAddress { emailAddress }
    defaultPhoneNumber { phoneNumber }
    note
    tags
    defaultAddress { address1 city province countryCodeV2 zip }
    addressesV2(first: 10) { nodes { id address1 city countryCodeV2 zip } }
  }
}

mutation CreateCustomer($input: CustomerInput!) {
  customerCreate(input: $input) {
    customer { id displayName }
    userErrors { field message }
  }
}

mutation UpdateCustomer($input: CustomerInput!) {
  customerUpdate(input: $input) {
    customer { id displayName note tags }
    userErrors { field message }
  }
}

query ListGiftCards($first: Int!, $after: String, $query: String) {
  giftCards(first: $first, after: $after, query: $query) {
    nodes {
      id
      lastCharacters
      enabled
      expiresOn
      balance { amount currencyCode }
      initialValue { amount currencyCode }
      customer { id displayName }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query GetGiftCard($id: ID!) {
  giftCard(id: $id) {
    id
    maskedCode
    enabled
    balance { amount currencyCode }
    transactions(first: 50) {
      nodes { id amount { amount currencyCode } processedAt note }
    }
  }
}

mutation CreateGiftCard($input: GiftCardCreateInput!) {
  giftCardCreate(input: $input) {
    giftCard { id lastCharacters balance { amount currencyCode } }
    giftCardCode
    userErrors { field message code }
  }
}

mutation CreditGiftCard($id: ID!, $creditInput: GiftCardCreditInput!) {
  giftCardCredit(id: $id, creditInput: $creditInput) {
    giftCardCreditTransaction { id amount { amount currencyCode } giftCard { id balance { amount } } }
    userErrors { field message code }
  }
}

mutation DebitGiftCard($id: ID!, $debitInput: GiftCardDebitInput!) {
  giftCardDebit(id: $id, debitInput: $debitInput) {
    giftCardDebitTransaction { id amount { amount currencyCode } giftCard { id balance { amount } } }
    userErrors { field message code }
  }
}

mutation DeactivateGiftCard($id: ID!) {
  giftCardDeactivate(id: $id) {
    giftCard { id enabled deactivatedAt }
    userErrors { field message code }
  }
}
